package br.com.mathinclui.auth.token;
import br.com.mathinclui.auth.security.SubjectType; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="auth_refresh_tokens") public class RefreshTokenSession { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=80) private String jti; @Enumerated(EnumType.STRING) @Column(name="subject_type",nullable=false,length=20) private SubjectType subjectType; @Column(name="subject_id",nullable=false) private Long subjectId; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="revoked_at") private Instant revokedAt; @Column(name="criado_em",nullable=false) private Instant criadoEm; protected RefreshTokenSession(){} public RefreshTokenSession(String jti,SubjectType subjectType,Long subjectId,Instant expiresAt,Instant criadoEm){this.jti=jti;this.subjectType=subjectType;this.subjectId=subjectId;this.expiresAt=expiresAt;this.criadoEm=criadoEm;} public String getJti(){return jti;} public SubjectType getSubjectType(){return subjectType;} public Long getSubjectId(){return subjectId;} public Instant getExpiresAt(){return expiresAt;} public Instant getRevokedAt(){return revokedAt;} public boolean isActiveAt(Instant instant){return revokedAt==null&&instant.isBefore(expiresAt);} public void revoke(Instant instant){if(revokedAt==null)revokedAt=instant;} }
